options {
    directory "/var/cache/bind";
    recursion no;
    allow-query { any; };
};
zone "banquehorizon.com" {
    type primary;
    file "/etc/bind/db.banquehorizon.com";
    allow-transfer { 203.0.113.11; };
    notify yes;
};
zone "113.0.203.in-addr.arpa" {
    type primary;
    file "/etc/bind/db.203.0.113";
};

options {
	directory "/var/cache/bind";

	dnssec-validation auto;

	listen-on-v6 { any; };
};

upstream api_bancaire {
    server 127.0.0.1:8081;
}

server {
    listen 8081;
    server_name 127.0.0.1;
    root /var/www/banquehorizon/backend;
    access_log /var/log/nginx/api-bancaire.access.log;
    location /v1/ {
        try_files $uri =404;
    }
}

server {
    listen 80 default_server;
    server_name _;
    return 404;
}

server {
    listen 80;
    server_name banquehorizon.com www.banquehorizon.com ebanking.banquehorizon.com agences.banquehorizon.com;
    return 301 https://$host$request_uri;
}

server {
    listen 443 ssl default_server;
    server_name _;
    ssl_certificate /etc/nginx/tls/banquehorizon.crt;
    ssl_certificate_key /etc/nginx/tls/banquehorizon.key;
    return 404;
}

server {
    listen 443 ssl;
    server_name banquehorizon.com www.banquehorizon.com;
    ssl_certificate /etc/nginx/tls/banquehorizon.crt;
    ssl_certificate_key /etc/nginx/tls/banquehorizon.key;
    root /var/www/banquehorizon/www;
    index index.html;
    gzip on;
    gzip_types text/css application/javascript application/json;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "DENY" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    access_log /var/log/nginx/www.access.log;
    error_page 404 /404.html;
    error_page 500 502 503 504 /50x.html;
    rewrite ^/credit-immo$ /produits/credits.html permanent;
    location / {
        try_files $uri $uri/ =404;
    }
    location /api/ {
        proxy_pass http://api_bancaire/v1/;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

server {
    listen 443 ssl;
    server_name ebanking.banquehorizon.com;
    ssl_certificate /etc/nginx/tls/banquehorizon.crt;
    ssl_certificate_key /etc/nginx/tls/banquehorizon.key;
    root /var/www/banquehorizon/ebanking;
    index index.html;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    add_header X-Frame-Options "DENY" always;
    add_header Cache-Control "no-store" always;
    access_log /var/log/nginx/ebanking.access.log;
    error_page 503 /maintenance.html;
    location / {
        try_files $uri $uri/ =404;
    }
    location = /connexion {
        return 503;
    }
    location /api/ {
        proxy_pass http://api_bancaire/v1/;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

server {
    listen 443 ssl;
    server_name agences.banquehorizon.com;
    ssl_certificate /etc/nginx/tls/banquehorizon.crt;
    ssl_certificate_key /etc/nginx/tls/banquehorizon.key;
    root /var/www/banquehorizon/agences;
    index index.html;
    autoindex off;
    access_log /var/log/nginx/agences.access.log;
    location / {
        try_files $uri $uri/ =404;
    }
}

:root { --encre: #12263a; --fond: #f6f8fb; --accent: #0b6e4f; --alerte: #b3261e; }
* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, sans-serif; color: var(--encre); background: var(--fond); line-height: 1.55; }
.bandeau { display: flex; justify-content: space-between; align-items: center; padding: 14px 24px; background: var(--encre); color: #fff; }
.bandeau a { color: #fff; text-decoration: none; margin-left: 18px; }
.marque { font-weight: 700; font-size: 1.25rem; margin-left: 0 !important; }
.bouton { background: var(--accent); padding: 6px 14px; border-radius: 4px; }
main { max-width: 960px; margin: 32px auto; padding: 0 20px; }
.carte { background: #fff; border: 1px solid #dbe3ec; border-radius: 8px; padding: 18px 22px; margin: 18px 0; }
table { border-collapse: collapse; width: 100%; }
th, td { text-align: left; padding: 8px 10px; border-bottom: 1px solid #e3e9f0; }
.erreur { color: var(--alerte); }
footer { text-align: center; color: #5a6b7d; padding: 24px; font-size: 0.9rem; }

document.addEventListener('DOMContentLoaded', function () {
  var cible = document.querySelector('[data-taux]');
  if (!cible) { return; }
  fetch('/api/taux.json').then(function (reponse) { return reponse.json(); }).then(function (taux) {
    cible.innerHTML = taux.produits.map(function (p) { return '<tr><td>' + p.nom + '</td><td>' + p.taux + ' %</td></tr>'; }).join('');
  }).catch(function () { cible.innerHTML = '<tr><td class="erreur" colspan="2">Taux indisponibles</td></tr>'; });
});

